+pub fn params(strategy: PocketStrategy) -> Pocket3DParams {
+    Pocket3DParams {
+        links: camcraft_motion::links::Links::ROUGH3D,
+        tool_diameter: D,
+        stepover: 4.0,
+        stock_to_leave: 0.5,
+        clearance_z: 25.0,
+        top_z: 14.0,
+        bottom_z: -14.0,
+        stepdown: 0.5,
+        feed: 500.0,
+        plunge_feed: 100.0,
+        climb: true,
+        strategy,
+        retract_z: None,
